UNITS = [{'id': 'PEDS-U304', 'ch': 36, 'n': 1, 'title': 'Inherited Tubular Disorders — Presentation & Fanconi', 'sec': 'ITD presentation and Fanconi · p162', 'qs': ['PEDS-C36-001', 'PEDS-C36-002', 'PEDS-C36-003', 'PEDS-C36-004', 'PEDS-C36-005', 'PEDS-C36-006', 'PEDS-C36-007', 'PEDS-C36-008', 'PEDS-C36-009', 'PEDS-C36-010', 'PEDS-C36-011', 'PEDS-C36-012', 'PEDS-C36-013', 'PEDS-C36-014'], 'guide': 'Tubular defects reduce reabsorption: water loss causes polyuria with compensatory polydipsia, electrolyte loss causes imbalance, and nutrient loss causes failure to thrive. Fanconi is a generalized proximal-tubule/type II RTA defect.'}, {'id': 'PEDS-U305', 'ch': 36, 'n': 2, 'title': 'Fanconi Syndrome — Acidification & Genetic Associations', 'sec': 'Fanconi associations · p162', 'qs': ['PEDS-C36-015', 'PEDS-C36-016', 'PEDS-C36-017', 'PEDS-C36-018', 'PEDS-C36-019', 'PEDS-C36-020', 'PEDS-C36-021', 'PEDS-C36-022', 'PEDS-C36-023', 'PEDS-C36-024', 'PEDS-C36-025', 'PEDS-C36-026', 'PEDS-C36-027', 'PEDS-C36-028'], 'guide': 'Fanconi retains distal urinary acidification (urine pH <5.5). Its associations include cystinosis, Lowe syndrome, Wilson disease and galactosemia; cystinosin failure traps cystine in lysosomes.'}, {'id': 'PEDS-U306', 'ch': 36, 'n': 3, 'title': 'Bartter Syndrome', 'sec': 'Bartter syndrome · p162–163', 'qs': ['PEDS-C36-029', 'PEDS-C36-030', 'PEDS-C36-031', 'PEDS-C36-032', 'PEDS-C36-033', 'PEDS-C36-034', 'PEDS-C36-035', 'PEDS-C36-036', 'PEDS-C36-037', 'PEDS-C36-038', 'PEDS-C36-039', 'PEDS-C36-040', 'PEDS-C36-041', 'PEDS-C36-042', 'PEDS-C36-043', 'PEDS-C36-044'], 'guide': 'Bartter is an autosomal-recessive ascending-loop defect beginning in infancy. Na-K-2Cl transport failure causes salt and calcium loss, RAAS activation, hypokalemic hypochloremic metabolic alkalosis, hypercalciuria/nephrocalcinosis; ROMK or Barttin-related chloride defects have key distinctions.'}, {'id': 'PEDS-U307', 'ch': 36, 'n': 4, 'title': 'Gitelman Syndrome', 'sec': 'Gitelman syndrome · p163', 'qs': ['PEDS-C36-045', 'PEDS-C36-046', 'PEDS-C36-047', 'PEDS-C36-048', 'PEDS-C36-049', 'PEDS-C36-050', 'PEDS-C36-051', 'PEDS-C36-052', 'PEDS-C36-053', 'PEDS-C36-054', 'PEDS-C36-055', 'PEDS-C36-056'], 'guide': 'Gitelman is an autosomal-recessive DCT disorder presenting in older children. Na-Cl and magnesium loss activates RAAS and causes hypokalemic hypochloremic metabolic alkalosis with hypomagnesemia.'}, {'id': 'PEDS-U308', 'ch': 36, 'n': 5, 'title': 'Liddle Syndrome & Evaluation', 'sec': 'Liddle syndrome and evaluation · p164', 'qs': ['PEDS-C36-057', 'PEDS-C36-058', 'PEDS-C36-059', 'PEDS-C36-060', 'PEDS-C36-061', 'PEDS-C36-062', 'PEDS-C36-063', 'PEDS-C36-064', 'PEDS-C36-065', 'PEDS-C36-066', 'PEDS-C36-067'], 'guide': 'Liddle is an autosomal-dominant gain-of-function ENaC disorder: sodium retention gives hypertension and suppressed aldosterone, while potassium loss produces hypokalemic metabolic alkalosis. Use acid-base status, BP, urinary calcium and magnesium to separate the inherited tubulopathies.'}]
